ALTER TABLE public.job_photos ADD COLUMN IF NOT EXISTS attribution_review_reason text;
UPDATE public.job_photos p SET attribution_review_reason = 'Legacy upload has no independently recorded uploader; review before reassignment.' WHERE NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id='job-photos' AND o.name=p.storage_path AND coalesce(o.owner_id,o.owner::text)=p.uploaded_by::text);
CREATE OR REPLACE FUNCTION public.enforce_job_photo_upload_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN IF NEW.uploaded_by IS DISTINCT FROM auth.uid() OR split_part(NEW.storage_path,'/',1) <> NEW.tenant_id::text OR split_part(NEW.storage_path,'/',2) <> NEW.job_id::text OR split_part(NEW.storage_path,'/',3) <> auth.uid()::text OR array_length(string_to_array(NEW.storage_path,'/'),1) <> 4 THEN RAISE EXCEPTION 'Photo upload belongs to a different cleaner or appointment. Please upload again.'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER enforce_job_photo_upload_identity BEFORE INSERT ON public.job_photos FOR EACH ROW EXECUTE FUNCTION public.enforce_job_photo_upload_identity();
CREATE UNIQUE INDEX job_photos_bound_upload_unique ON public.job_photos(storage_path) WHERE array_length(string_to_array(storage_path,'/'),1)=4;
ALTER POLICY "Employees view photos for their jobs" ON public.job_photos USING (tenant_id=public.current_tenant_id() AND uploaded_by=auth.uid() AND EXISTS (SELECT 1 FROM public.job_employees je WHERE je.job_id=job_photos.job_id AND je.employee_id=auth.uid()));
ALTER POLICY "Staff read assigned job photos" ON storage.objects USING (bucket_id='job-photos' AND (storage.foldername(name))[1]=public.current_tenant_id()::text AND (public.is_owner_or_manager() OR EXISTS (SELECT 1 FROM public.job_photos p JOIN public.job_employees je ON je.job_id=p.job_id WHERE p.storage_path=objects.name AND p.uploaded_by=auth.uid() AND je.employee_id=auth.uid())));
ALTER POLICY "Owner delete own job photos" ON storage.objects USING (bucket_id='job-photos' AND (storage.foldername(name))[1]=public.current_tenant_id()::text AND (public.is_owner_or_manager() OR (storage.foldername(name))[3]=auth.uid()::text OR owner=auth.uid()));